import React, { useState } from "react";
import { Link, useLocation, useNavigate } from "react-router-dom";
import logo from "../assets/comparify.jpg";

function Header() {
  const [active, setActive] = useState("home");
  const location = useLocation();
  const navigate = useNavigate();

  // Sirf Results page pe Back to Search dikhega
  const isResultsPage = location.pathname === "/results";

  return (
    <header className="header">
      <div className="logo-container">
        <img src={logo} alt="Comparify Logo" className="logo" />
        <h1 className="site-name">Comparify</h1>
      </div>

      <nav className="nav">

        {/* Sirf Results page pe Back to Search dikhega */}
        {isResultsPage && (
  <button
    onClick={() => { setActive("back"); navigate(-1); }}
    style={{
      background: "transparent",
      border: "none",
      color: "white",
      marginRight: "20px",
      fontSize: "16px",
      cursor: "pointer",
      transition: "0.3s",
      padding: "0",
      fontFamily: "Poppins, sans-serif"
    }}
    onMouseEnter={(e) => e.target.style.color = "#155fa0"}
    onMouseLeave={(e) => e.target.style.color = "white"}
  >
    ← Back to Search
  </button>
)}

        {/* Scroll link for How It Works */}
        <a
          href="/#how-it-works"
          onClick={() => setActive("how")}
          className={active === "how" ? "active-link" : ""}
        >
          How It Works
        </a>

        {/* Favorites Page */}
        <Link
          to="/favorites"
          onClick={() => setActive("favorites")}
          className={active === "favorites" ? "active-link" : ""}
        >
          Favorites
        </Link>

        {/* Sign In */}
        <Link
          to="/signin"
          onClick={() => setActive("signin")}
          className={active === "signin" ? "active-link" : ""}
        >
          Sign In
        </Link>

        {/* Sign Up */}
        <Link
          to="/signup"
          onClick={() => setActive("signup")}
          className={active === "signup" ? "active-link" : ""}
        >
          Sign Up
        </Link>

      </nav>
    </header>
  );
}

export default Header;
